// Simple endless runner based on IDEA.md
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');

  // Resize canvas to fill window
  function resize() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  }
  resize();
  window.addEventListener('resize', resize);

  // Game state
  let running = false;
  let gameOver = false;
  let score = 0;
  const speed = 5; // world scroll speed (px/frame)

  // Player definition
  const player = {
    width: 40,
    height: 40,
    x: canvas.width * 0.2,
    y: canvas.height - 60,
    vy: 0,
    jumpStrength: -12,
    gravity: 0.5,
    lane: 0, // -1 left, 0 center, 1 right
    laneOffset: 60,
  };

  function resetPlayer() {
    player.x = canvas.width * 0.2;
    player.y = canvas.height - 60;
    player.vy = 0;
    player.lane = 0;
  }

  // Obstacles
  const obstacles = [];
  const obstacleFreq = 120; // frames between obstacles
  let obstacleTimer = 0;

  function spawnObstacle() {
    const lane = Math.floor(Math.random() * 3) - 1; // -1,0,1
    const size = 40;
    const y = canvas.height - 60;
    const x = canvas.width + size;
    const offsetX = lane * player.laneOffset;
    obstacles.push({ x: x + offsetX, y: y - size, width: size, height: size, lane });
  }

  // Input handling
  function handleJump() {
    if (!running) return;
    if (player.vy === 0) player.vy = player.jumpStrength;
  }
  function handleLaneChange(dir) {
    if (!running) return;
    const newLane = Math.max(-1, Math.min(1, player.lane + dir));
    if (newLane !== player.lane) {
      player.lane = newLane;
      player.x = canvas.width * 0.2 + player.lane * player.laneOffset;
    }
  }

  document.addEventListener('keydown', e => {
    if (e.code === 'Space') handleJump();
    if (e.code === 'ArrowLeft') handleLaneChange(-1);
    if (e.code === 'ArrowRight') handleLaneChange(1);
    if (e.code === 'Enter' && gameOver) start();
  });
  document.addEventListener('click', () => {
    if (!running) return handleJump();
    if (gameOver) start();
  });

  // Collision detection
  function collides(a, b) {
    return a.x < b.x + b.width && a.x + a.width > b.x &&
           a.y < b.y + b.height && a.y + a.height > b.y;
  }

  // Game loop
  function update() {
    if (!running) return;
    // player physics
    player.vy += player.gravity;
    player.y += player.vy;
    if (player.y > canvas.height - 60) {
      player.y = canvas.height - 60;
      player.vy = 0;
    }
    // obstacles movement
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const obs = obstacles[i];
      obs.x -= speed;
      if (obs.x + obs.width < 0) obstacles.splice(i, 1);
      else if (collides(player, obs)) {
        running = false;
        gameOver = true;
      }
    }
    // spawn obstacles
    if (obstacleTimer <= 0) {
      spawnObstacle();
      obstacleTimer = obstacleFreq;
    } else {
      obstacleTimer--;
    }
    // score increments by distance travelled
    score += speed * 0.01;
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // background
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // player
    ctx.fillStyle = '#0ff';
    ctx.fillRect(player.x, player.y - player.height, player.width, player.height);
    // obstacles
    ctx.fillStyle = '#f00';
    for (const o of obstacles) {
      ctx.fillRect(o.x, o.y - o.height, o.width, o.height);
    }
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText(`Score: ${Math.floor(score)}`, 20, 30);
    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '40px sans-serif';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
      ctx.font = '20px sans-serif';
      ctx.fillText('Press Enter or Click to Restart', canvas.width / 2, canvas.height / 2 + 20);
    }
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }

  function start() {
    resetPlayer();
    obstacles.length = 0;
    obstacleTimer = 0;
    score = 0;
    gameOver = false;
    running = true;
  }

  // start automatically
  start();
  requestAnimationFrame(loop);
})();
